import{_ as t,o as a,c,a3 as i}from"./chunks/framework.CRbjHCyB.js";const g=JSON.parse('{"title":"格式化","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"格式化 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/cli/format"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/cli/format"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/format"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/format"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/format"}]]},"headers":[],"relativePath":"zh/clice/cli/format.md","filePath":"zh/clice/cli/format.md","lastUpdated":1790231062000}'),o={name:"zh/clice/cli/format.md"};function l(s,e,n,r,h,p){return a(),c("div",null,[...e[0]||(e[0]=[i(`<h1 id="格式化" tabindex="-1">格式化 <a class="header-anchor" href="#格式化" aria-label="Permalink to &quot;格式化&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>clice format</code> 对工作区中的文件运行 clang-format，同时启动多个进程，并沿用项目中已有的 <code>.clang-format</code> 配置。clice 自己不添加任何风格设置：风格来自 clang-format 自身的查找规则，即每个文件向上最近的那个 <code>.clang-format</code>。</p><p><strong>用法</strong>：<code>clice format [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--check] [--clang-format &lt;path&gt;] [--jobs &lt;n&gt;] [&lt;path&gt;...]</code></p><p>不带路径时，它格式化构建自身的文件：编译数据库中的每个翻译单元，以及它们包含的每个带 C 族后缀的文件——这些文件须位于工作区内，在构建树之外（构建树指根目录下存放编译数据库的目录，构建会在其中生成或拉取源文件），在其编译命令的系统包含目录之外，也在缓存目录之外。目录参数会把这个集合收窄到该目录下的文件；带 C 族后缀的文件参数则无论构建是否知道它都会被格式化。路径相对于工作区。<code>clice.toml</code> 中写有 <code>format = false</code> 的规则会把匹配到的文件排除在外，例如随项目附带的第三方库或生成的源文件：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;third_party/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gen/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">format = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>文件会被原地重写；符号链接指向的源文件会在其目标处重写，而目标也必须位于工作区内。<code>--check</code> 不改写任何文件，只打印 clang-format 会修改的地方，每处一条诊断，最后给出有多少个文件需要格式化。<code>--clang-format</code> 指定要运行的可执行文件，默认使用 <code>clang-format</code>，在 <code>PATH</code> 中查找。</p><p>退出码：<code>0</code> 表示所有文件都已格式化（带 <code>--check</code> 时表示不会有任何改动），<code>1</code> 表示 <code>--check</code> 发现了需要格式化的文件，<code>2</code> 表示本次运行未能完成——没有找到 clang-format 或它在某个文件上失败，工作区、其配置或某个编译数据库无法加载，或请求的配置不存在。</p>`,8)])])}const m=t(o,[["render",l]]);export{g as __pageData,m as default};
